public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || start.length != 2 || end.length != 2) {
        return "cannot be travelled";
    }

    // Check if start and end are within bounds
    if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n ||
        end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
        return "cannot be travelled";
    }

    // If start equals end, travel is possible
    if (start[0] == end[0] && start[1] == end[1]) {
        return "can be travelled";
    }

    // Build adjacency list
    List<List<int[]>> graph = new ArrayList<>();
    for (int i = 0; i < n * n; i++) {
        graph.add(new ArrayList<>());
    }

    if (paths != null) {
        for (int[] path : paths) {
            if (path == null || path.length != 4) {
                continue;
            }
            int x1 = path[0], y1 = path[1], x2 = path[2], y2 = path[3];
            if (x1 < 0 || x1 >= n || y1 < 0 || y1 >= n || x2 < 0 || x2 >= n || y2 < 0 || y2 >= n) {
                continue;
            }
            int node1 = x1 * n + y1;
            int node2 = x2 * n + y2;
            graph.get(node1).add(new int[]{x2, y2});
            graph.get(node2).add(new int[]{x1, y1});
        }
    }

    // BFS to check if end is reachable from start
    boolean[][] visited = new boolean[n][n];
    Queue<int[]> queue = new LinkedList<>();
    queue.offer(start);
    visited[start[0]][start[1]] = true;

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        int cx = current[0], cy = current[1];

        if (cx == end[0] && cy == end[1]) {
            return "can be travelled";
        }

        int node = cx * n + cy;
        for (int[] neighbor : graph.get(node)) {
            int nx = neighbor[0], ny = neighbor[1];
            if (!visited[nx][ny]) {
                visited[nx][ny] = true;
                queue.offer(new int[]{nx, ny});
            }
        }
    }

    return "cannot be travelled";
}

public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null) {
        throw new IllegalArgumentException("Input words cannot be null");
    }

    int len1 = word1.length();
    int len2 = word2.length();
    int sumLengths = len1 + len2;

    if (sumLengths == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }

    // Count common letters (case-insensitive)
    int[] count1 = new int[26];
    int[] count2 = new int[26];

    for (char c : word1.toCharArray()) {
        if (Character.isLetter(c)) {
            count1[Character.toUpperCase(c) - 'A']++;
        }
    }

    for (char c : word2.toCharArray()) {
        if (Character.isLetter(c)) {
            count2[Character.toUpperCase(c) - 'A']++;
        }
    }

    int common = 0;
    for (int i = 0; i < 26; i++) {
        common += Math.min(count1[i], count2[i]);
    }

    // Reduce the fraction common/sumLengths
    int numerator = common;
    int denominator = sumLengths;

    if (numerator == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }

    int gcd = gcd(numerator, denominator);
    numerator /= gcd;
    denominator /= gcd;

    if (denominator == 1) {
        return "appx(" + word1 + ", " + word2 + ") = " + numerator;
    } else {
        return "appx(" + word1 + ", " + word2 + ") = " + numerator + "/" + denominator;
    }
}

public static String convertDatesToWeekdays(String date) {
