public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }

    int ones = 0;
    int twos = 0;

    for (int num : nums) {
        // Update ones and twos based on current bit state
        // ones: bits that have appeared once
        // twos: bits that have appeared twice

        // If a bit is in twos, it should not be in ones (reset)
        // If a bit is in ones, it should not be in twos (reset)

        // New ones: bits that are in num and not in twos, or bits that are in ones and not in num
        // Actually, let's use the standard approach:

        // ones = (ones ^ num) & ~twos
        // twos = (twos ^ num) & ~ones

        int newOnes = (ones ^ num) & ~twos;
        int newTwos = (twos ^ num) & ~ones;

        ones = newOnes;
        twos = newTwos;
    }

    return ones;
}

