public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    int current = 1;
    for (int i = 0; i < n; i++) {
        result.add(current);
        if (current * 10 <= n) {
            current *= 10;
        } else {
            while (current % 10 == 9 || current + 1 > n) {
                current /= 10;
            }
            current++;
        }
    }
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }

    java.util.Set<Integer> uniqueElements = new java.util.HashSet<>();
    java.util.Set<Integer> seenElements = new java.util.HashSet<>();

    for (int num : nums) {
        if (seenElements.contains(num)) {
            uniqueElements.remove(num);
        } else {
            seenElements.add(num);
            uniqueElements.add(num);
        }
    }

    int sum = 0;
    for (int num : uniqueElements) {
        sum += num;
    }

    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }

    int[] dp = new int[n + 1];
    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        dp[i] = i; // worst case: all 1s
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            dp[i] = Math.min(dp[i], dp[i - square] + 1);
        }
    }

    return dp[n];
}

